using System;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class GangWarTests
    {
        static readonly Action<GangState> Save=s=>{};
        static GangTurfDefinition Area()=>GangTurfOptions.Defaults().Areas[0];
        static GangState State()=>new GangState{Gang="Mine",Reputation=123,Rank=1,TerritoriesEnabled=true,Turf=new GangTurfData{Owners={{1,"Mine"}}},Warfare=new GangWarData{AttacksEnabled=true,RivalsEnabled=true}};
        static GangWarAlert Alert()=>new GangWarAlert{Id="alert",Gang="Mine",Attacker="Enemy",Area=Area()};
        static GangState Warn(){Assert.True(GangWarTransactions.Alert(State(),Alert(),Save,out var s));return s;}
        static GangTurfAttempt Defense(GangState s)=>new GangTurfAttempt{Id="defense",Gang="Mine",PreviousOwner="Mine",Attacker="Enemy",WarAlertId="alert",Area=CharacterRules.Copy(s.Warfare.Alert.Area),Mode=GangTurfMode.Defense,WaveSize=3,Models=Enumerable.Repeat("g_m_y_famca_01",6).ToArray(),Radius=45,SecondsLimit=600};
        [Fact] public void OldSaveHasNoSimulationAndNoMigrationOfOwners(){var s=JsonConvert.DeserializeObject<GangState>("{\"Gang\":\"Mine\",\"Future\":7}");Assert.Null(s.Warfare);Assert.Null(s.Turf);Assert.False(new GangWarData().AttacksEnabled);Assert.False(new GangWarData().RivalsEnabled);Assert.False(new GangWarData().Reinforcements);}
        [Fact] public void AlertSnapshotsCoordinatesAndDoesNotTransferOrPay(){var s=State();var a=Alert();Assert.True(GangWarTransactions.Alert(s,a,Save,out var n));a.Area.Center.X=0;Assert.NotEqual(0,n.Warfare.Alert.Area.Center.X);Assert.Equal("Mine",n.Turf.Owners[1]);Assert.Null(s.Warfare.Alert);Assert.Equal(123,n.Reputation);Assert.Equal(0,n.Turf.Attempts);}
        [Fact] public void WarningCannotReplaceAnotherOrUseUnownedTerritory(){var s=Warn();Assert.False(GangWarTransactions.Alert(s,Alert(),Save,out _));s=State();s.Turf.Owners[1]="Other";Assert.False(GangWarTransactions.Alert(s,Alert(),Save,out _));}
        [Fact] public void DisabledOrForeignGangCannotReceiveWarning(){var s=State();s.Warfare.AttacksEnabled=false;Assert.False(GangWarTransactions.Alert(s,Alert(),Save,out _));s=State();s.Gang="Else";Assert.False(GangWarTransactions.Alert(s,Alert(),Save,out _));}
        [Fact] public void ActiveTerritoryOrInitiationBlocksWarning(){var s=State();s.Strength=new GangStrengthData{Pending=new GangStrengthAttempt()};Assert.False(GangWarTransactions.Alert(s,Alert(),Save,out _));s=Warn();GangTurfTransactions.Begin(s,Defense(s),Save,out s);Assert.False(GangWarTransactions.Alert(s,new GangWarAlert{Id="second",Gang="Mine",Attacker="Enemy",Area=Area()},Save,out _));}
        [Fact] public void DeadlineTransfersOnlyOneAreaAndCountsSeparateFromManualLoss(){var s=Warn();s.Turf.Owners[99]="Unknown";Assert.True(GangWarTransactions.Advance(s,"alert",120000,Save,out var n));Assert.Equal("Enemy",n.Turf.Owners[1]);Assert.Equal("Unknown",n.Turf.Owners[99]);Assert.Equal(1,n.Warfare.Unanswered);Assert.Equal(0,n.Turf.LostDefenses);Assert.Equal(0,n.Turf.Attempts);Assert.Equal(123,n.Reputation);Assert.Null(n.Warfare.Alert);Assert.Equal("unanswered",n.Warfare.History.Single().Result);Assert.False(GangWarTransactions.Advance(n,"alert",120000,Save,out _));}
        [Fact] public void ProgressIsMonotonicAndBounded(){var s=Warn();Assert.True(GangWarTransactions.Advance(s,"alert",1000,Save,out s));Assert.False(GangWarTransactions.Advance(s,"alert",999,Save,out _));Assert.False(GangWarTransactions.Advance(s,"alert",120001,Save,out _));Assert.False(GangWarTransactions.Advance(s,"other",2000,Save,out _));Assert.Equal(1000,s.Warfare.Alert.Elapsed);}
        [Fact] public void SuspendedActivityBlocksDeadlineMutation(){var s=Warn();s.Loyalty=new GangLoyaltyData{Pending=new GangLoyaltyAttempt()};Assert.False(GangWarTransactions.Advance(s,"alert",120000,Save,out _));Assert.Equal("Mine",s.Turf.Owners[1]);}
        [Fact] public void AffiliationOrOwnerChangeCannotBeOverwritten(){var s=Warn();s.Gang="Other";Assert.False(GangWarTransactions.Advance(s,"alert",120000,Save,out _));s=Warn();s.Turf.Owners[1]="External";Assert.False(GangWarTransactions.Advance(s,"alert",120000,Save,out _));}
        [Fact] public void DisableDismissesWarningWithoutLossAndOtherSettingsStay(){var s=Warn();Assert.True(GangWarTransactions.Configure(s,"attacks",false,Save,out s));Assert.Null(s.Warfare.Alert);Assert.False(s.Warfare.AttacksEnabled);Assert.True(s.Warfare.RivalsEnabled);Assert.Equal("Mine",s.Turf.Owners[1]);Assert.Equal(0,s.Warfare.Unanswered);Assert.Equal("dismissed",s.Warfare.History.Single().Result);}
        [Fact] public void IndependentSettingsAndUnknownFeatureRejected(){var s=State();Assert.True(GangWarTransactions.Configure(s,"reinforcements",true,Save,out s));Assert.True(s.Warfare.Reinforcements);Assert.True(GangWarTransactions.Configure(s,"rivals",false,Save,out s));Assert.False(s.Warfare.RivalsEnabled);Assert.True(s.Warfare.AttacksEnabled);Assert.False(GangWarTransactions.Configure(s,"invented",true,Save,out _));}
        [Fact] public void RespondConsumesWarningAndStartsDefenseInExactlyOneSave(){var s=Warn();int calls=0;Assert.True(GangTurfTransactions.Begin(s,Defense(s),n=>calls++,out var n));Assert.Equal(1,calls);Assert.Null(n.Warfare.Alert);Assert.Equal(1,n.Warfare.Responded);Assert.Equal("responded",n.Warfare.History.Single().Result);Assert.Equal("alert",n.Turf.Pending.WarAlertId);Assert.Equal(1,n.Turf.Attempts);Assert.Equal("Mine",n.Turf.Owners[1]);Assert.NotNull(s.Warfare.Alert);}
        [Fact] public void RespondCannotSwapAttackerAreaOrSnapshot(){var s=Warn();var p=Defense(s);p.Attacker="Other";Assert.False(GangTurfTransactions.Begin(s,p,Save,out _));p=Defense(s);p.Area.Name="Changed";Assert.False(GangTurfTransactions.Begin(s,p,Save,out _));p=Defense(s);p.WarAlertId="other";Assert.False(GangTurfTransactions.Begin(s,p,Save,out _));Assert.NotNull(s.Warfare.Alert);}
        [Fact] public void FailedResponseSaveKeepsWarningAndNoDefense(){var s=Warn();Assert.Throws<Exception>(()=>GangTurfTransactions.Begin(s,Defense(s),n=>throw new Exception(),out _));Assert.NotNull(s.Warfare.Alert);Assert.Null(s.Turf.Pending);Assert.Equal(0,s.Warfare.Responded);}
        [Fact] public void ResponseReplayCannotCreateSecondDefense(){var s=Warn();var p=Defense(s);GangTurfTransactions.Begin(s,p,Save,out s);Assert.True(GangTurfTransactions.Begin(s,p,n=>throw new Exception(),out s));Assert.Equal(1,s.Warfare.Responded);Assert.Equal(1,s.Turf.Attempts);}
        [Fact] public void RespondedDefenseWinUsesExistingReputationAndOwnership(){var s=Warn();GangTurfTransactions.Begin(s,Defense(s),Save,out s);for(int i=0;i<6;i++)GangTurfTransactions.Defeat(s,"defense",i,Save,out s);Assert.True(GangTurfTransactions.Capture(s,"defense",Save,out s));Assert.Equal(148,s.Reputation);Assert.Equal(1,s.Turf.Defenses);Assert.Equal(1,s.Warfare.Responded);Assert.Equal("Mine",s.Turf.Owners[1]);}
        [Fact] public void RespondedDefenseLossUsesExistingLossRules(){var s=Warn();GangTurfTransactions.Begin(s,Defense(s),Save,out s);Assert.True(GangTurfTransactions.End(s,"defense",true,Save,out s));Assert.Equal("Enemy",s.Turf.Owners[1]);Assert.Equal(1,s.Turf.LostDefenses);Assert.Equal(103,s.Reputation);Assert.Equal(0,s.Warfare.Unanswered);}
        [Fact] public void CancelledDefenseDoesNotRestoreAlertOrDuplicateResponse(){var s=Warn();GangTurfTransactions.Begin(s,Defense(s),Save,out s);Assert.True(GangTurfTransactions.End(s,"defense",false,Save,out s));Assert.Null(s.Warfare.Alert);Assert.Null(s.Turf.Pending);Assert.Equal("Mine",s.Turf.Owners[1]);Assert.Equal(1,s.Warfare.Responded);}
        [Fact] public void PartialAlertAndReadyDefenseSurviveReload(){var s=Warn();GangWarTransactions.Advance(s,"alert",43000,Save,out s);s=CharacterRules.Copy(s);Assert.Equal(43000,s.Warfare.Alert.Elapsed);GangTurfTransactions.Begin(s,Defense(s),Save,out s);for(int i=0;i<6;i++)GangTurfTransactions.Defeat(s,"defense",i,Save,out s);s=CharacterRules.Copy(s);Assert.True(s.Turf.Pending.Ready);Assert.Equal("alert",s.Turf.Pending.WarAlertId);}
        static GangState Rivals(){var s=State();s.Turf.Owners[1]="A";return s;}
        [Fact] public void RivalVictoryChangesOnlyForeignAreaWithoutPlayerReward(){var s=Rivals();Assert.True(GangWarTransactions.Rival(s,Area(),"B","A",true,"rival",Save,out s));Assert.Equal("B",s.Turf.Owners[1]);Assert.Equal(123,s.Reputation);Assert.Equal(0,s.Turf.Captures);Assert.Equal(1,s.Warfare.RivalBattles);Assert.Equal("rival_capture",s.Warfare.History.Single().Result);}
        [Fact] public void RivalDefenseCountsBattleWithoutChangingOwner(){var s=Rivals();Assert.True(GangWarTransactions.Rival(s,Area(),"B","A",false,"rival",Save,out s));Assert.Equal("A",s.Turf.Owners[1]);Assert.Equal("rival_defense",s.Warfare.History.Single().Result);}
        [Fact] public void RivalSimulationCannotAttackOrAwardPlayer(){var s=State();Assert.False(GangWarTransactions.Rival(s,Area(),"B","Mine",true,"rival",Save,out _));s=Rivals();Assert.False(GangWarTransactions.Rival(s,Area(),"Mine","A",true,"rival",Save,out _));}
        [Fact] public void RivalReplayAndStaleOwnerAreRejected(){var s=Rivals();GangWarTransactions.Rival(s,Area(),"B","A",true,"rival",Save,out s);Assert.False(GangWarTransactions.Rival(s,Area(),"B","A",true,"new",Save,out _));Assert.False(GangWarTransactions.Rival(s,Area(),"C","B",true,"rival",Save,out _));Assert.Equal(1,s.Warfare.RivalBattles);}
        [Fact] public void RivalSimulationStopsDuringWarningOrWhenDisabled(){var s=Warn();Assert.False(GangWarTransactions.Rival(s,Area(),"A","B",true,"rival",Save,out _));s=Rivals();s.Warfare.RivalsEnabled=false;Assert.False(GangWarTransactions.Rival(s,Area(),"B","A",true,"rival",Save,out _));}
        [Fact] public void EveryWarSaveFailureLeavesOriginalStateByteIdentical(){var s=Warn();var before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangWarTransactions.Advance(s,"alert",120000,n=>throw new Exception(),out _));Assert.Throws<Exception>(()=>GangWarTransactions.Configure(s,"attacks",false,n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));s=Rivals();before=JsonConvert.SerializeObject(s);Assert.Throws<Exception>(()=>GangWarTransactions.Rival(s,Area(),"B","A",true,"rival",n=>throw new Exception(),out _));Assert.Equal(before,JsonConvert.SerializeObject(s));}
        [Fact] public void HistoryBoundAndUnknownMetadataPreserved(){var s=Rivals();var j=JObject.FromObject(s);j["FutureRoot"]=7;j["Warfare"]["FutureWar"]="keep";s=j.ToObject<GangState>();for(int i=0;i<40;i++)Assert.True(GangWarTransactions.Rival(s,Area(),"B","A",false,"rival"+i,Save,out s));Assert.Equal(32,s.Warfare.History.Count);Assert.Equal("rival8",s.Warfare.History[0].Id);j=JObject.FromObject(s);Assert.Equal(7,(int)j["FutureRoot"]);Assert.Equal("keep",(string)j["Warfare"]["FutureWar"]);}
        [Fact] public void InvalidBooksAndOverflowAreProtected(){var s=Warn();s.Warfare.Unanswered=long.MaxValue;Assert.False(GangWarTransactions.Advance(s,"alert",120000,Save,out _));s.Warfare.Unanswered=-1;Assert.False(GangWarTransactions.Configure(s,"rivals",false,Save,out _));s=Warn();s.Warfare.Responded=long.MaxValue;Assert.False(GangTurfTransactions.Begin(s,Defense(s),Save,out _));s=Rivals();s.Warfare.RivalBattles=long.MaxValue;Assert.False(GangWarTransactions.Rival(s,Area(),"B","A",true,"rival",Save,out _));}
        [Fact] public void ReinforcedAttemptNeedsAllSixAndPreservesSnapshot(){var s=State();s.Turf.Owners[1]="Enemy";var p=new GangTurfAttempt{Id="capture",Gang="Mine",PreviousOwner="Enemy",Area=Area(),Mode=GangTurfMode.Attack,InitialDefenders=3,Radius=45,SecondsLimit=600,Models=Enumerable.Repeat("g_m_y_famca_01",6).ToArray()};Assert.True(GangTurfTransactions.Begin(s,p,Save,out s));for(int i=0;i<3;i++)GangTurfTransactions.Defeat(s,p.Id,i,Save,out s);Assert.False(s.Turf.Pending.Ready);s=CharacterRules.Copy(s);Assert.Equal(3,s.Turf.Pending.InitialDefenders);for(int i=3;i<6;i++)GangTurfTransactions.Defeat(s,p.Id,i,Save,out s);Assert.True(GangTurfTransactions.Capture(s,p.Id,Save,out s));Assert.Equal("Mine",s.Turf.Owners[1]);}
        [Theory][InlineData(1,780)][InlineData(2,720)][InlineData(3,660)][InlineData(4,600)][InlineData(5,540)][InlineData(6,480)][InlineData(8,420)][InlineData(10,360)][InlineData(12,300)][InlineData(14,240)]
        public void AttackIntervalsMatchSource(int owned,int seconds)=>Assert.Equal(seconds,GangWarRules.AttackSeconds(owned));
        [Theory][InlineData(3,1,3,6,false)][InlineData(3,2,3,6,true)][InlineData(3,3,3,6,true)][InlineData(3,2,6,6,false)][InlineData(0,1,3,6,false)][InlineData(2,1,2,5,true)]
        public void ReinforcementsTriggerOnceAtHalfInitialForce(int initial,int defeated,int spawned,int total,bool expected)=>Assert.Equal(expected,GangWarRules.Reinforce(initial,defeated,spawned,total));
        [Fact] public void ActiveClockHandlesPauseLongFramesAndSignedRollover(){Assert.Equal(0,GangWarRules.Delta(0,30000,false));Assert.Equal(1000,GangWarRules.Delta(0,30000,true));Assert.Equal(100,GangWarRules.Delta(int.MaxValue-50,int.MinValue+49,true));Assert.Equal(0,GangWarRules.Delta(100,0,true));}
        [Theory][InlineData(2,5,55)][InlineData(5,2,45)][InlineData(5,5,50)]public void RivalOddsMatchSource(int a,int d,int odds)=>Assert.Equal(odds,GangWarRules.WinChance(a,d));
        [Theory][InlineData("Hate",true)][InlineData("War",true)][InlineData("Neutral",false)][InlineData("Respect",false)][InlineData(null,false)]public void OnlyHostilityOrWarEligibleForPersonalAttacks(string attitude,bool result)=>Assert.Equal(result,GangWarRules.Hostile(attitude));
        [Fact] public void DeclarationSetsDirectedWarWithoutPaymentOrGlobalDefinitionChanges(){var w=new WalletData{Bank=123,Cash=42};int saves=0;Assert.True(GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","declaration",()=>saves++,out bool changed));Assert.True(changed);Assert.Equal(1,saves);var a=GangDiplomacyRules.Account(w.GangDiplomacy,"Mine","Enemy");Assert.Equal("War",a.Attitude);Assert.Equal(1,a.Declarations);Assert.Equal(0,a.Paid);Assert.Equal(123,w.Bank);Assert.Equal(42,w.Cash);Assert.Null(GangDiplomacyRules.Account(w.GangDiplomacy,"Enemy","Mine"));}
        [Fact] public void DeclarationReplayDoesNotSaveOrDuplicateCounter(){var w=new WalletData();GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","id",()=>{},out _);Assert.True(GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","id",()=>throw new Exception(),out bool changed));Assert.False(changed);Assert.Equal(1,w.GangDiplomacy.Accounts[0].Declarations);Assert.False(GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","other",()=>{},out _));}
        [Fact] public void DeclarationFailureRollsBackWholeBook(){var w=new WalletData();Assert.Throws<Exception>(()=>GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","id",()=>throw new Exception(),out _));Assert.Null(w.GangDiplomacy);Assert.False(GangDiplomacyTransactions.DeclareWar(w,State(),"Mine","Neutral","id",()=>{},out _));}
        [Fact] public void DeclarationRejectsPendingDefenseAndCorruptDiplomacy(){var s=Warn();GangTurfTransactions.Begin(s,Defense(s),Save,out s);Assert.False(GangDiplomacyTransactions.DeclareWar(new WalletData(),s,"Enemy","Neutral","id",()=>{},out _));var w=new WalletData{GangDiplomacy=new GangDiplomacyData{Accounts={new GangDiplomacyAccount()}}};Assert.False(GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","id",()=>{},out _));}
        [Fact] public void PeaceAgreementAfterDeclarationUsesExistingPriceAndCooldown(){var w=new WalletData{Bank=2000};GangDiplomacyTransactions.DeclareWar(w,State(),"Enemy","Neutral","war",()=>{},out _);Assert.True(GangDiplomacyTransactions.Negotiate(w,State(),"Enemy","Neutral",new GangDiplomacyOptions(),new DateTime(2026,10,26),"peace",()=>{},out _));Assert.Equal("Hate",w.GangDiplomacy.Accounts[0].Attitude);Assert.Equal(1,w.GangDiplomacy.Accounts[0].Declarations);Assert.Equal(1000,w.Bank);Assert.False(GangDiplomacyTransactions.Negotiate(w,State(),"Enemy","Neutral",new GangDiplomacyOptions(),new DateTime(2026,10,26),"peace2",()=>{},out _));}
        [Fact] public void ConfigAndAlertRejectOutOfRangeOrCorruptValues(){Assert.True(new GangWarOptions().Valid);Assert.False(new GangWarOptions{ResponseSeconds=0}.Valid);Assert.False(new GangWarOptions{RivalMaxSeconds=299}.Valid);var a=Alert();a.Elapsed=120001;Assert.False(a.Valid);a=Alert();a.Attacker="Mine";Assert.False(a.Valid);var s=Warn();s.Warfare.History.Add(new GangWarRecord());Assert.False(s.Warfare.Valid);}
    }
}
